import { test } from 'node:test';
import assert from 'node:assert/strict';
import { processBatch } from '../src/pipeline.js';

test('limits concurrent calls and returns outputs in input order', async () => {
  let active = 0;
  let peak = 0;
  const output = await processBatch([3, 1, 2, 4], { concurrency: 2, attempts: 1, process: async value => {
    active++;
    peak = Math.max(peak, active);
    await new Promise(resolve => setTimeout(resolve, value * 5));
    active--;
    return value * 2;
  }});
  assert.ok(peak >= 1 && peak <= 2);
  assert.deepEqual(output, [6, 2, 4, 8]);
});

test('retries an item independently and succeeds on its last attempt', async () => {
  const calls = new Map();
  const result = await processBatch(['a', 'b'], { concurrency: 2, attempts: 3, process: value => {
    calls.set(value, (calls.get(value) ?? 0) + 1);
    if (value === 'a' && calls.get(value) < 3) throw new Error('temporary');
    return value.toUpperCase();
  }});
  assert.deepEqual(result, ['A', 'B']);
  assert.equal(calls.get('a'), 3);
  assert.equal(calls.get('b'), 1);
});

test('reports a permanent failure and does not exceed its attempt limit', async () => {
  let calls = 0;
  await assert.rejects(processBatch([1], { concurrency: 1, attempts: 2, process: async () => { calls++; throw new Error('failed'); } }), /failed/);
  assert.equal(calls, 2);
});

test('rejects invalid options and handles an empty list', async () => {
  const process = value => value;
  await assert.rejects(processBatch([1], { concurrency: 0, attempts: 1, process }), TypeError);
  await assert.rejects(processBatch([1], { concurrency: 1, attempts: 0, process }), TypeError);
  assert.deepEqual(await processBatch([], { concurrency: 2, attempts: 1, process }), []);
});

