import { test } from 'node:test';
import assert from 'node:assert/strict';
import { summarize } from '../src/summary.js';

test('sums finite values by category without mutating records', () => {
  const records = [{category:'a',value:2},{category:'b',value:3},{category:'a',value:4}];
  const original = JSON.stringify(records);
  assert.deepEqual(summarize(records), {a:6,b:3});
  assert.equal(JSON.stringify(records), original);
});

test('rejects invalid records', () => {
  assert.throws(() => summarize([{category:'a',value:NaN}]), TypeError);
  assert.throws(() => summarize([{category:'',value:1}]), TypeError);
});

