import assert from 'node:assert/strict';
import { processBatch } from '/work/src/pipeline.js';
import { summarize } from '/work/src/summary.js';

test('permanent undefined rejection is not converted to success', async () => {
  let rejected = false;
  try { await processBatch([1], {concurrency:1,attempts:2,process:()=>{throw undefined;}}); } catch { rejected = true; }
  assert.equal(rejected, true);
});
test('batch maintains concurrency and order with synchronous and asynchronous processing', async () => {
  let active=0, peak=0;
  const output=await processBatch([4,3,2,1,0], {concurrency:2,attempts:1,process: async value=>{active++;peak=Math.max(peak,active); await new Promise(resolve=>setTimeout(resolve,value*4));active--;return value;}});
  assert.deepEqual(output,[4,3,2,1,0]);
  assert.ok(peak >= 1 && peak <= 2);
});
test('batch rejects invalid fractional and infinite limits', async () => {
  await assert.rejects(processBatch([1],{concurrency:1.5,attempts:1,process:x=>x}),TypeError);
  await assert.rejects(processBatch([1],{concurrency:1,attempts:Infinity,process:x=>x}),TypeError);
});
test('a concurrent temporary failure does not replace the permanent error', async () => {
  let slowCalls=0;
  await assert.rejects(processBatch(['permanent','slow'], {concurrency:2,attempts:2,process:async item=>{
    if(item==='permanent') throw new Error('permanent');
    await new Promise(resolve=>setTimeout(resolve,15));
    if(++slowCalls===1) throw new Error('temporary');
    return 'ok';
  }}), error=>error?.message==='permanent');
});
test('summary correctly handles object prototype property names', () => {
  const result=summarize([{category:'__proto__',value:2},{category:'constructor',value:3},{category:'toString',value:4}]);
  assert.equal(Object.hasOwn(result,'__proto__'),true);
  assert.equal(result.__proto__,2);
  assert.equal(result.constructor,3);
  assert.equal(result.toString,4);
});
test('summary rejects missing, nonnumeric and infinite values', () => {
  for(const record of [{category:'a'},{category:'a',value:'1'},{category:'a',value:Infinity},{category:4,value:1}]) assert.throws(()=>summarize([record]),TypeError);
});
test('summary handles empty input', () => assert.deepEqual(summarize([]),{}));

