import type { Task } from "../../entities/task/task.types.auto";
import { tasks_status as taskStatuses } from "../../generated/database/database.enums";

export const groupTasks = (input: {
  tasks: Task[];
  search: string;
  projectCode: string;
}): Map<Task["status"], Task[]> => {
  const columns = new Map(taskStatuses.map((status): [Task["status"], Task[]] => [status, []]));
  const search = input.search.toLowerCase();
  for (const task of input.tasks) {
    if (
      `${input.projectCode}-${task.number} ${task.type} ${task.title} ${task.description} ${task.assignee} ${task.aiCategory}`
        .toLowerCase()
        .includes(search)
    )
      columns.get(task.status)?.push(task);
  }
  return columns;
};

